-- ═══════════════════════════════════════════════════════════════
-- Миграция 0026: сопоставление организаций по номеру дома
-- ═══════════════════════════════════════════════════════════════
--
-- Миграция 0025 перечисляла допустимые суффиксы дома («2с», «2к», «2стр»), и
-- этого оказалось мало: в данных встречаются «15К» с ЗАГЛАВНОЙ кириллической
-- К, «10А», «2» без корпуса вовсе. 330 вызовов по 129 адресам остались без
-- метки — как раз более ранние, где адреса записаны иначе.
--
-- Здесь сопоставление идёт по ЧИСЛУ дома: из строки берутся ведущие цифры и
-- сравниваются как число. Тогда «15», «15к1», «15К», «15стр3», «15А» — это
-- один дом, а «150» — уже другой, потому что число не совпадает.
--
-- Улица сравнивается без учёта регистра и с нормализацией пробелов: в базе
-- встречаются и «Саляма Адиля улица», и «улица Саляма Адиля».
-- ═══════════════════════════════════════════════════════════════

-- Ведущее число дома. IMMUTABLE — чтобы годилось для индекса, если понадобится.
CREATE OR REPLACE FUNCTION house_num(h text) RETURNS integer
LANGUAGE sql IMMUTABLE AS $$
    SELECT NULLIF((regexp_match(COALESCE(h, ''), '^\s*(\d+)'))[1], '')::integer
$$;

-- Снимок до правки (0025 уже создавал свой; этот — перед вторым проходом)
DROP TABLE IF EXISTS address_org_snapshot_0026;
CREATE TABLE address_org_snapshot_0026 AS
    SELECT id, organization AS old_organization, now() AS snapshot_at
    FROM addresses;

-- Правила: улица (подстрока, без регистра) + номер дома (число).
-- Дома перечислены явно — комплекс может занимать несколько номеров.
WITH rules(org, street_pat, houses) AS (VALUES
    ('ГБУЗ «ПКБ № 1 им. Н. А. Алексеева ДЗМ»',                       '%загородное шоссе%',     ARRAY[2]),
    ('ГБУЗ «ПКБ № 4 им. П. Б. Ганнушкина ДЗМ»',                      '%потешная%',             ARRAY[3]),
    ('ГБУЗ «ГКБ № 67 им. Л. А. Ворохобова ДЗМ»',                     '%саляма адиля%',         ARRAY[2]),
    ('ГБУЗ «ГКБ им. А. К. Ерамишанцева ДЗМ»',                        '%ленская%',              ARRAY[15]),
    ('ГБУЗ «ГКБ № 1 им. Н. И. Пирогова ДЗМ»',                        '%ленинский проспект%',   ARRAY[8, 10]),
    ('ГБУЗ «ГКБ им. Ф. И. Иноземцева ДЗМ»',                          '%фортунатовская%',       ARRAY[1]),
    ('ГБУЗ «НИИ СП им. Н. В. Склифосовского ДЗМ»',                   '%большая сухаревская%',  ARRAY[3]),
    ('ГБУЗ «НИИ СП им. Н. В. Склифосовского ДЗМ»',                   '%грохольский%',          ARRAY[12]),
    ('ГБУЗ «Инфекционная клиническая больница № 2 ДЗМ»',             '%соколиной горы%',       ARRAY[15]),
    ('ФКУ «СИЗО-1 УФСИН России по г. Москве» («Матросская Тишина»)', '%матросская тишина%',    ARRAY[18]),
    ('ФКУ «СИЗО-3 УФСИН России по г. Москве» («Красная Пресня»)',    '%силикатный проезд%',    ARRAY[11]),
    ('ФКУ «СИЗО-4 УФСИН России по г. Москве» («Медведь»)',           '%вилюйская%',            ARRAY[4]),
    ('ФКУ «СИЗО-5 УФСИН России по г. Москве» («Водник»)',            '%выборгская%',           ARRAY[20])
)
UPDATE addresses a
SET organization = r.org
FROM rules r
WHERE lower(a.street) LIKE r.street_pat
  AND house_num(a.house) = ANY(r.houses);

-- Контроль: сколько адресов помечено и сколько вызовов с маркёром в поводе
-- всё ещё без метки
SELECT (SELECT count(*) FROM addresses WHERE organization IS NOT NULL AND organization <> '') AS адресов_помечено,
       (SELECT count(*) FROM calls c LEFT JOIN addresses a ON a.id = c.address_id
        WHERE c.reason ~* '^МЭ:\s*из\s|сизо'
          AND (a.organization IS NULL OR a.organization = '')) AS вызовов_без_метки;
